"""Build the editable HTML slide deck from reviewed analysis outputs."""
from pathlib import Path
import json
from html import escape

root=Path(__file__).resolve().parents[1]
a=json.loads((root/'analysis/dataset_audit.json').read_text())
m=json.loads((root/'analysis/market_analysis.json').read_text())
f=json.loads((root/'analysis/scenarios.json').read_text())
slides=[]
def card(title,body,cls=''):
    return f'<article class="card {cls}"><h3>{title}</h3>{body}</article>'
def grid(*cards,cols=3):
    return f'<div class="grid c{cols}">'+''.join(cards)+'</div>'
def metric(number,label):
    return f'<div class="metric"><strong>{number}</strong><span>{label}</span></div>'
def table(headers,rows):
    return '<table><thead><tr>'+''.join(f'<th>{h}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table>'
def note(t):return f'<div class="note">{t}</div>'
def slide(section,title,body,source='Расчёты Digital Cat$ по синтетическому датасету VK, сентябрь 2026.',cls=''):
    i=len(slides)+1
    slides.append(f'<section class="slide {cls}" id="s{i}"><header><b>Digital Cat$</b><span>VK CASE CHAMP 2026</span><span>{section}</span></header><h1>{title}</h1><main>{body}</main><footer><span>{source}</span><b>{i:02d} / '+('08' if i<=8 else 'Приложения')+'</b></footer></section>')

